@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;700&display=swap");

:root {
  --canvas: #f5f4f0;
  --surface: rgba(255, 255, 255, 0.86);
  --surface-strong: rgba(255, 255, 255, 0.96);
  --ink: #161616;
  --ink-soft: #4f4d49;
  --border: rgba(22, 22, 22, 0.09);
  --border-strong: rgba(22, 22, 22, 0.16);
  --shadow: 0 24px 70px rgba(17, 17, 17, 0.06);
  --radius-xl: 32px;
  --radius-lg: 22px;
  --radius-md: 16px;
  --shell-width: 1200px;
}

html {
  font-size: 16px;
  min-height: 100%;
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(circle at top right, rgba(0, 0, 0, 0.05), transparent 28%),
    linear-gradient(180deg, #faf9f6 0%, var(--canvas) 100%);
  color: var(--ink);
  font-family: "Space Grotesk", sans-serif;
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover {
  color: inherit;
}

.shell {
  width: min(var(--shell-width), calc(100vw - 2rem));
  margin: 0 auto;
}

.page-chrome {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  padding: 1rem 0 0;
  backdrop-filter: blur(18px);
}

.site-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.25rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.72);
  box-shadow: var(--shadow);
}

.brandmark {
  display: inline-flex;
  flex-direction: column;
  gap: 0.1rem;
}

.brandmark__eyebrow,
.eyebrow,
.stat-card__label,
.section-header__eyebrow,
.breadcrumb,
.mission-chip,
.metric-label,
.signal-item__meta {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.74rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brandmark__eyebrow,
.eyebrow,
.section-header__eyebrow,
.breadcrumb,
.metric-label,
.signal-item__meta {
  color: var(--ink-soft);
}

.brandmark__title {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.site-nav__link,
.button-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1rem;
  border-radius: 999px;
  border: 1px solid transparent;
  transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease;
}

.site-nav__link:hover,
.button-link:hover {
  transform: translateY(-1px);
  background: rgba(255, 255, 255, 0.84);
  border-color: var(--border);
}

.site-main {
  flex: 1;
  padding: 2rem 0 4rem;
}

.site-footer {
  padding: 0 0 2rem;
}

.site-footer__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem 0 0;
  border-top: 1px solid var(--border);
}

.site-footer__title {
  font-weight: 700;
}

.site-footer__copy {
  color: var(--ink-soft);
  font-size: 0.95rem;
}

.site-footer__link {
  color: var(--ink-soft);
}

.dashboard {
  display: grid;
  gap: 1.5rem;
}

.hero-panel,
.surface-panel,
.stat-card,
.mission-card,
.lead-card,
.signal-card,
.surface-score-card,
.detail-panel {
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.hero-panel,
.detail-panel--hero {
  padding: clamp(1.5rem, 4vw, 3rem);
  background:
    linear-gradient(140deg, rgba(255, 255, 255, 0.98), rgba(255, 255, 255, 0.72)),
    radial-gradient(circle at right top, rgba(0, 0, 0, 0.07), transparent 32%);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 1.5rem;
  align-items: end;
}

.hero-copy h1,
.section-header__title,
.page-heading,
.mission-card__title,
.lead-card__title,
.detail-panel__title {
  margin: 0;
  letter-spacing: -0.05em;
